        triggered = clock.tick(minute)
        if triggered:
            queue.submit(f"check@{minute}", lab.repo)
        lab.event("clock-ticked", f"时钟走到第 {minute} 分钟",
                  {"seen": before}, {"seen": sorted(clock.emitted), "triggered": triggered, "jobs": list(queue.jobs)})


