def compact_history(history, keep_constraint):
    finding = history[1]["content"]
    retained = [{"role": "summary",
                 "content": f"上次检查实得 {finding['actual']} 分，预期 {finding['expected']} 分。"}]
    if keep_constraint:
        retained.insert(0, history[0])
    return retained + [history[-1]]


