    lab.event("job-submitted", "立即返回任务 ID，主循环可继续工作", {}, queue.poll("job-1"))
    lab.event("parent-continued", "主循环在结果到达前整理修改说明",
              {"blocked": False}, {"note": "已把单价乘件数", "job": "job-1"})
    if not failed:
        queue.advance("job-1")
