def receive_message(inbox, envelope):
    if envelope["id"] in inbox:
        return "duplicate"
    if envelope["to"] != "reviewer" or envelope["type"] != "review-request":
        return "unroutable"
    inbox[envelope["id"]] = envelope
    return "accepted"


